                // by definition of true_count:
                //    true_count(mask_seq, i+1) = true_count(mask_seq, i) + 1
                // and hence the (true_count(...)-1) % m = true_count(mask_seq,i) % m = j
                let v = vals[j];
                result.push(v);
                // advance j, cycling
                j = (j + 1) % m;
                // re‐establish j == true_count(mask_seq, i+1) % m
                // since we just had
                //    true_count(mask_seq, i+1) = true_count(mask_seq, i) + 1
                // and old j = true_count(mask_seq, i) % m,
                // new j = (old j + 1) % m = true_count(mask_seq, i+1) % m
